/** Every theme the library ships. */
export type ThemeId =
  | "anime"
  | "archive"
  | "aurora"
  | "bauhaus"
  | "blueprint"
  | "brutal"
  | "clay"
  | "corporate"
  | "crypto"
  | "eco"
  | "fashion"
  | "finance"
  | "food"
  | "forest"
  | "gaming"
  | "glass"
  | "instrument"
  | "ios"
  | "luxury"
  | "medical"
  | "monochrome"
  | "neon"
  | "night"
  | "nordic"
  | "pastel"
  | "retro"
  | "sakura"
  | "swiss"
  | "travel"
  | "vaporwave"
  | "verdant"
  | "y2k";

/** Whether a theme reads as light or as dark. */
export type ThemeAppearance = "light" | "dark";

/** One entry of the theme catalogue. */
export interface ThemeEntry {
  id: ThemeId;
  name: string;
  nameZh: string;
  appearance: ThemeAppearance;
  file: string;
  roles: number;
}

/** Every theme the library ships, as `themes/index.json` lists them. */
export type ThemeCatalogue = ThemeEntry[];

/** The themes that read as light, and the ones that read as dark. */
export interface ThemeIndex {
  version: string;
  prefix: string;
  default: ThemeId;
  combined: string;
  switcher: string;
  themes: ThemeCatalogue;
}

