/** Input / Textarea / Select — the sizes it can be rendered at. */
export type InputSize = "sm" | "md" | "lg";
export interface InputProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "input";
  size?: InputSize;
  /** Which member of the family this is. Each one is its own class: um-input, um-textarea, um-select. */
  control?: "input" | "textarea" | "select";
  /** The hint text for the input and the textarea. It takes the muted placeholder role, not the body colour. */
  placeholder?: string;
  /** Makes the control inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** Keeps the value visible but stops it being edited. The library does not repaint a readonly control — it is not a state it measures. */
  readonly?: boolean;
  /** The control's value, bound with v-model in Vue. Leave it out and the control holds whatever the reader typed; bind it and the control answers to the binding. */
  modelValue?: string;
}

/** Input Number · 数字输入框 — A field for a number, with a pair of buttons that step it up and down. The buttons are real buttons, so they are in the tab order and the browser announces them; the browser's own spin buttons are taken away so there is only one pair. */
export type InputNumberVariant = "left";
/** Input Number — the sizes it can be rendered at. */
export type InputNumberSize = "small" | "medium" | "large";
export interface InputNumberProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "input-number";
  variant?: InputNumberVariant;
  size?: InputNumberSize;
  /** The number in the field. It is the input's own value, not a class — a class cannot carry a number. */
  value?: number;
  /** The smallest number the field accepts. It is the input's own min attribute, so the browser enforces it. */
  min?: number;
  /** The largest number the field accepts. It is the input's own max attribute. */
  max?: number;
  /** How much one press of a button changes the value. It is the input's own step attribute, and the browser's arrow keys use it too. */
  step?: number;
  /** Which side of the field the pair of buttons sits on. The right position is the base class on its own; the left position adds um-input-number--left. */
  controlsPosition?: "right" | "left";
  /** Makes the field and both buttons inert. It uses the real disabled attribute, so they leave the tab order. */
  disabled?: boolean;
  /** The number in the field, bound with v-model in Vue. Leave it out and the `value` prop is the number; bind it and the field answers to the binding. */
  modelValue?: number;
  /** Keeps the number visible but stops it being edited. It is the native readonly attribute, so the browser refuses the edit. The library does not repaint a read-only field — it is not a state it measures. */
  readonly?: boolean;
}

/** Input OTP · 验证码输入 — A row of one-character fields for a code the reader has been sent. Each box is a real input that holds one character, so the browser's own keyboard, autofill and password manager all still apply to it. */
export type InputOtpVariant = "boxed" | "underline";
/** Input OTP — the sizes it can be rendered at. */
export type InputOtpSize = "sm" | "md" | "lg";
export interface InputOtpProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "input-otp";
  variant?: InputOtpVariant;
  size?: InputOtpSize;
  /** The code, as one string. Each character goes into the box at that position; a class cannot carry a code. */
  value?: string;
  /** How many boxes there are. It is the host's number of characters, not something the class can say. */
  length?: number;
  /** Hides what is typed, the way a password field does. It is the input's own type, so the password manager and the reader's own setting still apply. */
  masked?: boolean;
  /** The accessible name of the row. It becomes the group's aria-label, because the boxes are named by their position and the row itself needs a name of its own. */
  label?: string;
  /** Makes every box inert. It uses the real disabled attribute, so they leave the tab order. */
  disabled?: boolean;
  /** Keeps the code visible but stops it being edited. It is the native readonly attribute, so the browser refuses the edit. The library does not repaint a read-only box — it is not a state it measures. */
  readonly?: boolean;
  /** The bound code. It answers to `v-model` as well as to `value`, and the binding wins when it is there. */
  modelValue?: string;
}

/** Input Tag · 标签输入 — A field that holds the tags already chosen, and an empty place to type the next one. Removing a tag needs a script; the shapes of the tag and of its remove button do not. */
export type InputTagVariant = "primary" | "success" | "warning" | "danger";
/** Input Tag — the sizes it can be rendered at. */
export type InputTagSize = "sm" | "md" | "lg";
export interface InputTagProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "input-tag";
  variant?: InputTagVariant;
  size?: InputTagSize;
  /** The text in the empty part of the field. */
  value?: string;
  /** The hint in the empty part of the field. */
  placeholder?: string;
  /** The accessible name of the field. It becomes the input's aria-label. */
  label?: string;
  /** Makes the field inert. It uses the real disabled attribute on the input, so it leaves the tab order and the field paints the flat control surface. */
  disabled?: boolean;
  /** Keeps the text visible but stops it being edited. It is the native readonly attribute, so the browser refuses the edit. The library does not repaint a read-only field — it is not a state it measures. */
  readonly?: boolean;
  /** The bound value. It answers to `v-model` as well as to `value`, and the binding wins when it is there. */
  modelValue?: string;
}

/** Mention · 提及 — A field with a list of people under it. The reader types, the host decides which names to offer, and each name is a button that carries an avatar slot and an @name. */
export type MentionVariant = "bordered" | "plain" | "round";
/** Mention — the sizes it can be rendered at. */
export type MentionSize = "sm" | "md" | "lg";
export interface MentionProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "mention";
  variant?: MentionVariant;
  size?: MentionSize;
  /** The text in the field. */
  value?: string;
  /** The hint in the empty field. */
  placeholder?: string;
  /** The accessible name of the field. It becomes the input's aria-label. */
  label?: string;
  /** The text in the field, bound with v-model in Vue. Leave it out and the `value` prop is the text; bind it and the field answers to the binding. */
  modelValue?: string;
  /** Makes the field inert. It uses the real disabled attribute on the input, so it leaves the tab order and the field paints the flat control surface. */
  disabled?: boolean;
  /** Keeps the text visible but stops it being edited. It is the native readonly attribute, so the browser refuses the edit. The library does not repaint a read-only field — it is not a state it measures. */
  readonly?: boolean;
}

/** Radio — the sizes it can be rendered at. */
export type RadioSize = "sm" | "md" | "lg";
export interface RadioProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "radio";
  size?: RadioSize;
  /** Selects this option. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes the radio inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The name the group shares. Radios with the same name are one group, and only one of them can be checked. */
  name?: string;
  /** The value submitted while this option is selected. */
  value?: string;
  /** Whether this option is the selected one, bound with v-model in Vue. Leave it out and the `checked` prop is the state; bind it and the option answers to the binding. Inside a radio group the group decides instead. */
  modelValue?: boolean;
  /** Puts a frame around the circle and its text, so the two read as one chip. */
  border?: boolean;
}

/** Radio Group · 单选框组 — A set of radios that share one name and belong to one field. The group is a fieldset, so the browser groups the circles for the form and for the screen reader. */
export type RadioGroupVariant = "stacked" | "inline";
/** Radio Group — the sizes it can be rendered at. */
export type RadioGroupSize = "sm" | "md" | "lg";
export interface RadioGroupProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "radio-group";
  variant?: RadioGroupVariant;
  size?: RadioGroupSize;
  /** The name every option in the group shares. It is the native name attribute, and it is what makes the group a group: the browser keeps exactly one of the options picked. */
  name?: string;
  /** The value one option submits while it is picked. */
  value?: string;
  /** The value that is picked in the group, bound with v-model in Vue. The options inside the group follow it. Leave it out and the group's own `checked` and `value` props describe the single option it renders. */
  modelValue?: string;
  /** Picks one option. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes one option inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** Which way the options run. The stacked run is the base class on its own; the inline run adds um-radio-group--inline. */
  direction?: "stacked" | "inline";
  /** The text of the group's legend. A group with no legend still needs an accessible name of its own. */
  label?: string;
  /** How the options are drawn. The radio run leaves the options as they are; the button run turns each one into a chip with a frame of its own. */
  type?: "radio" | "button";
}

/** Rate · 评分 — A row of stars the reader sets by choosing one. The stars are real radio buttons under a drawn shape, so the value is the browser's own value and the group is the browser's own group. */
export type RateVariant = "success" | "warning" | "danger";
/** Rate — the sizes it can be rendered at. */
export type RateSize = "small" | "medium" | "large";
export interface RateProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "rate";
  variant?: RateVariant;
  size?: RateSize;
  /** How many stars are filled. It is the checked radio's value, not a class — a class cannot carry a number. */
  value?: number;
  /** How many stars the group has. The stylesheet ships five positions, so a group longer than that needs more rules. */
  max?: number;
  /** The colour of the filled stars. The primary colour is the base class on its own; the other three add um-rate--success, um-rate--warning or um-rate--danger. */
  color?: "primary" | "success" | "warning" | "danger";
  /** Makes the group inert. It uses the real disabled attribute on the radios, so it leaves the tab order. */
  disabled?: boolean;
  /** How many stars are filled, bound with v-model in Vue. Leave it out and the `value` prop is the score; bind it and the group answers to the binding. */
  modelValue?: number;
  /** Writes the score beside the stars, so the number is written down and not only counted. */
  showScore?: boolean;
}

export interface SliderProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "slider";
  /** The lowest value the slider accepts. */
  min?: number;
  /** The highest value the slider accepts. */
  max?: number;
  /** How much one arrow key press moves the value. */
  step?: number;
  /** The current value. It is written to the value attribute, so it round-trips through a form. */
  value?: number;
  /** Makes the slider inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** Stands the slider on its end, so the value runs from the bottom up. */
  vertical?: boolean;
  /** The slider's own value, bound with v-model in Vue. Leave it out and the `value` prop is the value; bind it and the slider answers to the binding. */
  modelValue?: number;
}

/** Switch — the sizes it can be rendered at. */
export type SwitchSize = "sm" | "md" | "lg";
export interface SwitchProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "switch";
  size?: SwitchSize;
  /** Turns the setting on. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes the switch inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The name the value is submitted under. */
  name?: string;
  /** The value submitted while the switch is on. */
  value?: string;
  /** The switch's own state, bound with v-model in Vue. Leave it out and the `checked` prop is the state; bind it and the switch answers to the binding. */
  modelValue?: boolean;
  /** Says the switch is busy. The track dims and the switch stops taking clicks. */
  loading?: boolean;
  /** Writes the state inside the track instead of on a thumb beside it. The active and inactive slots are what it writes. */
  inlinePrompt?: boolean;
}

/** Time Picker · 时间选择器 — A field for a time of day. It is a real <input type="time"> inside a box the library draws, so the browser validates the hour, the arrow keys walk the segments and the reader's own clock opens it. */
export type TimePickerVariant = "single" | "range";
/** Time Picker — the sizes it can be rendered at. */
export type TimePickerSize = "sm" | "md" | "lg";
export interface TimePickerProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "time-picker";
  variant?: TimePickerVariant;
  size?: TimePickerSize;
  /** The time in the field. It is the input's own value, in the browser's own format — a class cannot carry a time. */
  value?: string;
  /** The earliest time the field accepts. It is the input's own min attribute, so the browser enforces it and marks the field out of range when it is not met. */
  min?: string;
  /** The latest time the field accepts. It is the input's own max attribute. */
  max?: string;
  /** How fine the time is, in seconds. It is the input's own step attribute, so the arrow keys move by it too. */
  step?: number;
  /** Makes the time necessary. It is the native required attribute, so the browser asks for it. */
  required?: boolean;
  /** Makes the field inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** Whether the field holds one time or two. The single field is the base class on its own; the range field adds um-time-picker--range. */
  type?: "single" | "range";
  /** The time in the field, bound with v-model in Vue. Leave it out and the `value` prop is the time; bind it and the field answers to the binding. */
  modelValue?: string;
  /** Keeps the time visible but stops it being edited. It is the native readonly attribute, so the browser refuses the edit. The library does not repaint a read-only field — it is not a state it measures. */
  readonly?: boolean;
}

/** Time Select · 时间选择器 — A choice of time of day, as a native <select>. The option list is the platform's own, so the reader gets the system's own picker and its keyboard behaviour; the library draws the field and the arrow around it. */
export type TimeSelectVariant = "bordered" | "filled";
/** Time Select — the sizes it can be rendered at. */
export type TimeSelectSize = "sm" | "md" | "lg";
export interface TimeSelectProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "time-select";
  variant?: TimeSelectVariant;
  size?: TimeSelectSize;
  /** The chosen time. It is the select's own value — a class cannot carry a time. */
  value?: string;
  /** The first time in the list. The list is the host's data: a class cannot carry the times either. */
  start?: string;
  /** The last time in the list. */
  end?: string;
  /** How far apart the times are, in seconds. Half an hour is the default; an hour is 3600. */
  step?: number;
  /** The accessible name of the field. It becomes the select's aria-label, because the library does not draw a label of its own. */
  label?: string;
  /** Makes the field inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The chosen time, bound with v-model in Vue. Leave it out and the `value` prop is the chosen time; bind it and the field answers to the binding. */
  modelValue?: string;
}

/** Tree Select · 树选择器 — A tree you pick a leaf from. The branches are disclosures, so the browser opens and closes them, and the leaf that is picked is a real radio, so the browser keeps exactly one of them picked. */
export type TreeSelectVariant = "plain" | "lines";
/** Tree Select — the sizes it can be rendered at. */
export type TreeSelectSize = "sm" | "md" | "lg";
export interface TreeSelectProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tree-select";
  variant?: TreeSelectVariant;
  size?: TreeSelectSize;
  /** The name every leaf in the tree shares. It is the native name attribute, and it is what makes the leaves a group: the browser keeps exactly one of them picked. */
  name?: string;
  /** The value one leaf submits while it is picked. It is also what the leaf says when the caller gives it no name of its own. */
  value?: string;
  /** The name of the thing the branch holds. */
  label?: string;
  /** Picks the leaf. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes the leaf inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The value the picked leaf submits, bound with v-model in Vue. Leave it out and the `value` prop is that value; bind it and the tree answers to the binding. */
  modelValue?: string;
  /** Draws a box in front of every leaf instead of a circle, so a leaf reads as something that can be ticked rather than something that can be picked. */
  showCheckbox?: boolean;
}

/** Upload · 上传 — A file input and the list of the files that were chosen. The input is a real one, so the browser's own dialog opens and the files are chosen with the browser's own picker. */
export type UploadVariant = "list" | "text";
/** Upload — the sizes it can be rendered at. */
export type UploadSize = "sm" | "md" | "lg";
export interface UploadProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "upload";
  variant?: UploadVariant;
  size?: UploadSize;
  /** Lets more than one file be chosen at a time. It is the native multiple attribute. */
  multiple?: boolean;
  /** Which file types the picker offers. It is the native accept attribute, so the browser filters the list. */
  accept?: string;
  /** Makes the upload inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The name the chosen files are submitted under. It is the native name attribute. */
  name?: string;
  /** How the chosen files are shown. The list layout is the base class on its own; the text layout adds um-upload--text. */
  layout?: "list" | "text";
  /** Where one file has got to. It is a class on the item: no class is the waiting state, and the other three are um-upload__item--uploading, um-upload__item--done and um-upload__item--error. */
  status?: "default" | "uploading" | "done" | "error";
  /** Whether the chosen files are shown under the trigger. The list is there unless the host says otherwise. */
  showFileList?: boolean;
}

/** Virtual Select · 虚拟列表选择器 — A long list of choices that the browser only lays out near the viewport. The rows far away are skipped, and the browser is told how tall such a row is, so the scrollbar is right without every row being built. */
export type VirtualSelectVariant = "bordered" | "plain";
/** Virtual Select — the sizes it can be rendered at. */
export type VirtualSelectSize = "sm" | "md" | "lg";
export interface VirtualSelectProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "virtual-select";
  variant?: VirtualSelectVariant;
  size?: VirtualSelectSize;
  /** The label of the option that is chosen. It is the radio's own value, so the choice is the browser's and not the library's. */
  value?: string;
  /** The bound value. It answers to `v-model` as well as to `value`, and the binding wins when it is there. */
  modelValue?: string;
  /** The labels in the list, separated by commas. The wrapper draws one option per label; the markup writes the options out. */
  options?: string;
  /** The text that names the list and stands in for a choice. It is the accessible name of the listbox, so the browser announces it when the reader reaches the list. The library has no field to write a selection into, so the placeholder is what the list is called. */
  placeholder?: string;
  /** The height of the scroller. It is a length and not a number of pixels: how tall the window onto the list is belongs to the host's page. */
  height?: string;
}

/** Avatar · 头像 — A small picture of a person. It takes a photo, a pair of initials or an icon, and it keeps the shape of whichever mood it is in. */
export type AvatarVariant = "circle" | "square";
/** Avatar — the sizes it can be rendered at. */
export type AvatarSize = "sm" | "md" | "lg" | "xl";
export interface AvatarProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "avatar";
  variant?: AvatarVariant;
  size?: AvatarSize;
  /** The alternative text of the photo. Leave it empty when the name is already written next to the avatar. */
  alt?: string;
}

/** Badge · 徽标 — A small marker that counts or names a state, attached to something else. It comes in a solid fill and a soft tint, so a page can let what matters come forward and the rest recede. */
export type BadgeVariant = "primary" | "success" | "warning" | "danger" | "info" | "soft-primary" | "soft-success" | "soft-warning" | "soft-danger" | "soft-info";
export interface BadgeProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "badge";
  variant?: BadgeVariant;
  /** Puts a dot in front of the label, in the badge's own foreground colour. */
  dot?: boolean;
}

/** Calendar · 日历 — One month laid out as a seven-column grid. It draws the month and marks the days; which month to show is the host's business, because a grid cannot know which months exist. */
export type CalendarVariant = "bordered" | "plain";
/** Calendar — the sizes it can be rendered at. */
export type CalendarSize = "sm" | "md" | "lg";
export interface CalendarProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "calendar";
  variant?: CalendarVariant;
  size?: CalendarSize;
  /** The month to draw, written as YYYY-MM. The calendar has no navigation of its own, so the host decides which month this is. */
  month?: string;
  /** The seven column names, separated by commas. They are written out rather than derived, so a month can start on Monday or on Sunday, and so a host can name the columns in its own language. */
  weekdays?: string;
  /** The date that is today, written as YYYY-MM-DD. The day it names takes the today marker. */
  today?: string;
  /** The date the reader has picked, written as YYYY-MM-DD. The day it names takes the selected marker. */
  selected?: string;
  /** The dates that cannot be picked, written as YYYY-MM-DD and separated by commas. The days they name are marked with aria-disabled, so the reader is told they cannot be picked. */
  disabled?: string;
}

/** Card · 卡片 — A surface that groups one thing: a title, a body, a footer. Its border, radius, shadow and fill all come from the mood, so one card reads correctly in all thirty-two of them. */
export type CardVariant = "frosted";
export interface CardProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "card";
  variant?: CardVariant;
}

/** Carousel · 轮播图 — Slides the reader scrolls through, with a button at each end of a slide that moves to the neighbouring one. The track is a real scroller, so the browser does the scrolling and the snapping. */
export type CarouselVariant = "plain" | "spaced";
/** Carousel — the sizes it can be rendered at. */
export type CarouselSize = "sm" | "md" | "lg";
export interface CarouselProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "carousel";
  variant?: CarouselVariant;
  size?: CarouselSize;
  /** The prefix of the ids of the slides. Every slide needs an id of its own, because that id is what the buttons point at, and two carousels on one page cannot share ids. */
  name?: string;
  /** The name of the track, read out before the slides. A scrollable region has to carry a name, or the reader is told about a scroll box and nothing else. */
  label?: string;
}

/** Cascader · 级联选择器 — Options in levels, opened one level at a time. Every level is a disclosure, so the browser does the opening and the closing and the state survives a reload. */
export type CascaderVariant = "inline" | "flyout";
/** Cascader — the sizes it can be rendered at. */
export type CascaderSize = "sm" | "md" | "lg";
export interface CascaderProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "cascader";
  variant?: CascaderVariant;
  size?: CascaderSize;
  /** Opens a level. It is the native open attribute on the details, so the browser keeps the state. */
  open?: boolean;
  /** Where the level below opens. The inline run is the base class on its own; the flyout run adds um-cascader--flyout. */
  layout?: "inline" | "flyout";
  /** The text of one option. An option with no text needs an accessible name of its own. */
  label?: string;
  /** Makes the cascader inert. A level is a disclosure rather than a form control, so it cannot carry the disabled attribute: the whole tree refuses the pointer instead. */
  disabled?: boolean;
}

/** Collapse · 折叠面板 — A panel that opens and closes. It is a real disclosure, so the browser does the opening and the closing and the state survives a reload. */
export type CollapseVariant = "plain" | "card";
/** Collapse — the sizes it can be rendered at. */
export type CollapseSize = "sm" | "md" | "lg";
export interface CollapseProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "collapse";
  variant?: CollapseVariant;
  size?: CollapseSize;
  /** Opens the panel. It is the native open attribute on the details, so the browser keeps the state. */
  open?: boolean;
  /** The text of the header. A panel with no text needs an accessible name of its own. */
  title?: string;
}

/** Descriptions · 描述列表 — The facts about one thing, as label and value pairs. It is a definition list, so a screen reader announces each label before the value it belongs to. */
export type DescriptionsVariant = "plain" | "bordered";
export interface DescriptionsProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "descriptions";
  variant?: DescriptionsVariant;
  /** How many pairs sit in one row. It is written to the `--um-descriptions-columns` custom property, because a class cannot carry a number. */
  columns?: number;
  /** The width of the label column, so the values line up under each other. It is written to the `--um-descriptions-label-width` custom property. */
  labelWidth?: string;
}

export interface EmptyProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "empty";
}

/** Image · 图片 — A frame for a picture: it holds the space the picture will take, shows a placeholder while there is none, and decides how the picture fills that space. */
export type ImageVariant = "cover" | "contain" | "fill" | "rounded" | "circle" | "bordered";
/** Image — the sizes it can be rendered at. */
export type ImageSize = "sm" | "md" | "lg";
export interface ImageProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "image";
  variant?: ImageVariant;
  size?: ImageSize;
  /** Where the picture is. An empty source leaves the placeholder standing in. */
  src?: string;
  /** The text a reader gets instead of the picture. An empty alt is right for a picture that only decorates the page. */
  alt?: string;
  /** The line under the frame. A caption is a caption for the picture, so it belongs under it and not on top of it. */
  caption?: string;
  /** How the picture fills the frame. The cover run is the base class on its own; the other two add um-image--contain and um-image--fill. */
  fit?: "cover" | "contain" | "fill";
  /** The shape of the frame. The square run is the base class on its own; the other two add um-image--rounded and um-image--circle. */
  shape?: "square" | "rounded" | "circle";
  /** Puts a rule around the frame. It is a class rather than an attribute, because the rule is a picture of the frame and not a state of it. */
  bordered?: boolean;
  /** Says the picture failed to load, so the placeholder stands in for it. */
  error?: boolean;
}

/** Infinite Scroll · 无限滚动 — A feed the reader can scroll a long way through, and a sentinel at the end of it that says what comes next. The library cannot load anything: it provides the container, the skipped layout and the sentinel, and the host decides what to load. */
export type InfiniteScrollVariant = "bordered" | "plain";
/** Infinite Scroll — the sizes it can be rendered at. */
export type InfiniteScrollSize = "sm" | "md" | "lg";
export interface InfiniteScrollProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "infinite-scroll";
  variant?: InfiniteScrollVariant;
  size?: InfiniteScrollSize;
  /** How many items the feed has. The wrapper writes one item per entry, and the stylesheet skips the ones the reader cannot see. */
  items?: number;
  /** Which of the three moments the sentinel is in. It is a class on the sentinel: the wrapper has to be told, because the library cannot know what the host is loading. */
  state?: "loading" | "loaded" | "end";
  /** How tall the scrolling box is. The library cannot guess it: a box that is not given a height never scrolls, because its content is what gives it one. */
  height?: string;
  /** What the end state says. */
  endText?: string;
}

/** Progress · 进度条 — How much of something is done. The bar is a groove with a fill inside it, and the fill takes its width from the host. */
export type ProgressVariant = "success" | "warning" | "danger";
export interface ProgressProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "progress";
  variant?: ProgressVariant;
  /** How much is done, as a percentage of the track. It is written to the inline width of the bar. */
  value?: number;
  /** The text under the bar. */
  label?: string;
}

/** Result · 结果 — The end of a flow: one statement of what happened, a line of explanation, and the way out. It is the whole answer on one screen, not a toast that disappears. */
export type ResultVariant = "success" | "warning" | "danger" | "info";
export interface ResultProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "result";
  variant?: ResultVariant;
  /** What happened. It should be a real heading element, so the page keeps its outline. */
  title?: string;
  /** The line under the title. */
  subtitle?: string;
}

/** Segmented · 分段控制器 — A row of choices that show which one is picked, drawn as radios under a shared frame. The browser keeps the selection, so the group behaves like the radio group it is. */
export type SegmentedVariant = "soft" | "solid" | "ghost";
/** Segmented — the sizes it can be rendered at. */
export type SegmentedSize = "sm" | "md" | "lg";
export interface SegmentedProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "segmented";
  variant?: SegmentedVariant;
  size?: SegmentedSize;
  /** The name every radio in the row shares. It is what makes the segments one group: the browser keeps exactly one of them picked. */
  name?: string;
  /** The value one segment submits while it is picked. */
  value?: string;
  /** Picks one segment. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes one segment inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** The name of the whole row, read out before the segments. A row with no name of its own needs an accessible name from somewhere. */
  label?: string;
}

/** Skeleton · 骨架屏 — The shape of content that has not arrived yet. Three placeholder shapes and, if the motion is welcome, a shimmer over them. */
export type SkeletonVariant = "text" | "circle" | "block";
export interface SkeletonProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "skeleton";
  variant?: SkeletonVariant;
  /** Which placeholder shape to draw. */
  shape?: "text" | "circle" | "block";
  /** Shimmers the placeholder while the content loads. The animation is wrapped in a prefers-reduced-motion query, so a user who asked for less motion gets a still placeholder. */
  animated?: boolean;
  /** How wide the placeholder is, as a percentage of its container. A line of text usually wants a width under 100. */
  width?: number;
}

/** Statistic · 统计数值 — One number with the name of what it counts. The number is the largest thing on the block and everything else is sized around it. */
export type StatisticVariant = "success" | "warning" | "danger";
export interface StatisticProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "statistic";
  variant?: StatisticVariant;
  /** What the number counts. */
  title?: string;
  /** The number, written the way it should be read: `9,999` and not `9999.0`. */
  value?: string;
}

/** Table · 表格 — Rows of records in columns. It is a real table, so the column names travel with the cells and a screen reader can read a row across. */
export type TableVariant = "striped" | "bordered";
export interface TableProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "table";
  variant?: TableVariant;
  /** What the empty cell says when there are no records. */
  emptyText?: string;
}

/** Tag · 标签 — A label for one piece of data — a category, a state, a filter. The outlined member of the chip family, so it can sit beside a filled badge without either of them winning. */
export type TagVariant = "primary" | "success" | "warning" | "danger";
export interface TagProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tag";
  variant?: TagVariant;
}

/** Timeline · 时间线 — What happened, in order. An ordered list with a rail down one side and a dot at each entry, so the order is in the structure and not only in the picture. */
export type TimelineVariant = "success" | "warning" | "danger";
export interface TimelineProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "timeline";
  variant?: TimelineVariant;
  /** When it happened. It is a time element inside the wrapper, so the machine-readable value and the written one travel together. */
  timestamp?: string;
}

/** Tour · 引导 — A walkthrough that points at one thing on the page and says what to do with it. The ring is the thing being pointed at, the card is what the tour says, and the dots are how far along the walkthrough is. Moving from one step to the next is the host's job. */
export type TourVariant = "bottom" | "top" | "left" | "right";
/** Tour — the sizes it can be rendered at. */
export type TourSize = "sm" | "md" | "lg";
export interface TourProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tour";
  variant?: TourVariant;
  size?: TourSize;
  /** Where the card sits relative to the thing it points at. The card below is the base class on its own; the other three add um-tour--top, um-tour--left and um-tour--right. */
  placement?: "bottom" | "top" | "left" | "right";
  /** The name of the step. */
  title?: string;
  /** The sentence that says what to do. */
  content?: string;
  /** Which step the walkthrough is on. It is the dot that is filled in. */
  step?: number;
  /** How many steps the walkthrough has. It is how many dots there are. */
  total?: number;
}

/** Transfer · 穿梭框 — Two lists side by side with a button between them: what is available on one side, what has been chosen on the other. The whole thing is a form, so the move is a submission. */
export type TransferVariant = "horizontal" | "vertical";
/** Transfer — the sizes it can be rendered at. */
export type TransferSize = "sm" | "md" | "lg";
export interface TransferProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "transfer";
  variant?: TransferVariant;
  size?: TransferSize;
  /** The name the ticked options are submitted under. It is the native name attribute, and the source and the target list use different names so the host can tell them apart. */
  name?: string;
  /** The value one option submits while it is ticked. */
  value?: string;
  /** Ticks one option. It is the native checked attribute, not a class. */
  checked?: boolean;
  /** Makes one option, or one of the move buttons, inert. It uses the real disabled attribute, so it leaves the tab order. */
  disabled?: boolean;
  /** Which way the two panels are laid out. The horizontal run is the base class on its own; the vertical run adds um-transfer--vertical. */
  direction?: "horizontal" | "vertical";
}

/** Tree · 树 — Things inside things. Every branch is a disclosure, so the browser opens and closes it and the state survives a reload. */
export type TreeVariant = "plain" | "lines";
/** Tree — the sizes it can be rendered at. */
export type TreeSize = "sm" | "md" | "lg";
export interface TreeProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tree";
  variant?: TreeVariant;
  size?: TreeSize;
  /** Opens the branch. It is the native open attribute on the details, so the browser keeps the state. */
  open?: boolean;
  /** The name of the thing the branch holds. A branch with no text needs an accessible name of its own. */
  label?: string;
}

/** Virtualized Table · 虚拟表格 — A long table the browser is not asked to lay out in full. The rows far from the viewport are skipped and given a placeholder size, so the cost of the list is what is near it. */
export type VirtualTableVariant = "bordered" | "plain";
/** Virtualized Table — the sizes it can be rendered at. */
export type VirtualTableSize = "sm" | "md" | "lg";
export interface VirtualTableProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "virtual-table";
  variant?: VirtualTableVariant;
  size?: VirtualTableSize;
  /** How many rows the list has. The wrapper writes one row per record, and the stylesheet skips the ones the reader cannot see. */
  rows?: number;
  /** The column names, separated by commas. */
  columns?: string;
  /** How tall the scrolling box is. The library cannot guess it: a box that is not given a height never scrolls, because its content is what gives it one. */
  height?: string;
  /** That there is nothing to show. The body says so instead of writing the rows. */
  empty?: boolean;
}

/** Virtualized Tree · 虚拟树 — A tree so large that the browser is asked to lay out only the branches near the reader. Every branch is still a disclosure, so the browser opens and closes it and the state survives a reload. */
export type VirtualTreeVariant = "plain" | "lines";
/** Virtualized Tree — the sizes it can be rendered at. */
export type VirtualTreeSize = "sm" | "md" | "lg";
export interface VirtualTreeProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "virtual-tree";
  variant?: VirtualTreeVariant;
  size?: VirtualTreeSize;
  /** How deep the tree goes. The wrapper writes that many levels of branches. */
  depth?: number;
  /** How many branches each level has. The wrapper multiplies them out, so a depth of four and six branches is a thousand leaves. */
  branches?: number;
  /** How tall the scrolling box is. The library cannot guess it: a box that is not given a height never scrolls, because its content is what gives it one. */
  height?: string;
}

/** Anchor · 锚点 — A column of links to the sections of the page, with a rule down the side so the reader can see that they are a list of places rather than a list of links. The section being read is marked with aria-current, because CSS cannot work out what is on screen. */
export type AnchorVariant = "plain";
export interface AnchorProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "anchor";
  variant?: AnchorVariant;
  /** The accessible name of the nav element. Every anchor on a page needs its own, or the screen reader announces them all as the same thing. */
  label?: string;
}

/** Backtop · 回到顶部 — A round button that takes the reader back to the top of the page. It is a link to a fragment, so it works with the keyboard alone and needs no scroll listener to appear — it is simply there. */
export type BacktopVariant = "soft" | "inline";
/** Backtop — the sizes it can be rendered at. */
export type BacktopSize = "sm" | "md" | "lg";
export interface BacktopProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "backtop";
  variant?: BacktopVariant;
  size?: BacktopSize;
  /** Whether the button sits in the flow of the page instead of floating over it. It adds um-backtop--inline. */
  inline?: boolean;
  /** The fragment the link points at. The page needs an element with that id for the link to go anywhere. */
  target?: string;
  /** The accessible name of the link. The arrow is a shape and says nothing, so the name has to come from somewhere. */
  label?: string;
}

/** Breadcrumb · 面包屑 — The path to the page you are on, as a list of links. The separators between the steps are drawn by the stylesheet, not written into the markup as characters. */
export type BreadcrumbVariant = "slash";
export interface BreadcrumbProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "breadcrumb";
  variant?: BreadcrumbVariant;
  /** The mark between the steps. The chevron is the base class on its own; the slash adds um-breadcrumb--slash. */
  separator?: "chevron" | "slash";
  /** The accessible name of the nav element. Every breadcrumb on a page needs its own, or the screen reader announces them all as the same thing. */
  label?: string;
}

/** Dropdown · 下拉菜单 — A row of actions that stays out of the way until it is wanted. The trigger is a <summary>, so the panel opens and closes with the browser's own disclosure behaviour. */
export type DropdownVariant = "end";
/** Dropdown — the sizes it can be rendered at. */
export type DropdownSize = "sm" | "md" | "lg";
export interface DropdownProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "dropdown";
  variant?: DropdownVariant;
  size?: DropdownSize;
  /** Which edge of the trigger the panel lines up with. The start placement is the base class on its own; the end placement adds um-dropdown--end. */
  placement?: "start" | "end";
  /** The text on the trigger. A trigger with no text still needs an accessible name of its own. */
  label?: string;
  /** Whether the dropdown is switched off. A disabled dropdown never opens. It adds um-dropdown--disabled. */
  disabled?: boolean;
  /** Whether the menu draws a rule between its items. It adds um-dropdown--divided. */
  divided?: boolean;
}

/** Menu · 菜单 — A list of places to go, with groups that fold away. The groups are <details> elements, so the browser opens and closes them and keeps them open across a reload. */
export type MenuVariant = "horizontal";
export interface MenuProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "menu";
  variant?: MenuVariant;
  /** Which way the entries run. The vertical menu is the base class on its own; the horizontal menu adds um-menu--horizontal. */
  direction?: "vertical" | "horizontal";
  /** Which entry is the current one. It is the um-menu__active class on that entry's item. */
  active?: string;
  /** Which way the entries run. This is Element Plus's name for the `direction` prop; either one of them lays the menu out. */
  mode?: "vertical" | "horizontal";
}

/** Pagination — the sizes it can be rendered at. */
export type PaginationSize = "sm";
export interface PaginationProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "pagination";
  size?: PaginationSize;
  /** How many records there are. It is what the total line and the last page number are counted from. */
  total?: number;
  /** Which page is open. It is the aria-current="page" on that page's item. */
  currentPage?: number;
  /** How many records one page holds. */
  pageSize?: "10" | "20" | "50" | "100";
  /** Whether the whole pager is inert. The arrows become real disabled buttons and the page numbers say so the way a disabled button does. */
  disabled?: boolean;
  /** Whether the pager disappears when there is only one page to be on. It adds um-pagination--hidden. */
  hideOnSinglePage?: boolean;
}

/** Steps · 步骤条 — The order of a job, one step per entry, with the step you are on picked out and the steps already done marked as finished. */
export type StepsVariant = "vertical";
export interface StepsProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "steps";
  variant?: StepsVariant;
  /** Which way the steps run. The horizontal run is the base class on its own; the vertical run adds um-steps--vertical. */
  direction?: "horizontal" | "vertical";
  /** Where the step stands. It is a class on the item: no class is the waiting state, and the other four are um-steps__item--active, um-steps__item--success, um-steps__item--error and um-steps__item--danger. */
  status?: "default" | "active" | "success" | "error" | "danger";
  /** Where the step that is being worked on stands. This is Element Plus's name for the `status` prop; either one of them says it. */
  processStatus?: "default" | "active" | "success" | "error" | "danger";
  /** Which step is being worked on, counted from one. That step carries the running state; zero leaves the states where the markup put them. */
  active?: number;
  /** Whether the title and the description stand in the middle of the step rather than at its start. It adds um-steps--align-center. */
  alignCenter?: boolean;
  /** Whether the run is the simple one: the titles stand in a row and the descriptions and the line are not drawn. It adds um-steps--simple. */
  simple?: boolean;
}

/** Tabs · 标签页 — One row of tabs over several panels of content. The tabs are radio inputs, so the browser keeps the selection, the focus and the arrow keys without a line of script. */
export type TabsVariant = "card";
export interface TabsProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tabs";
  variant?: TabsVariant;
  /** The name the radios share. Two tab groups with different names can be open at the same time. */
  name?: string;
  /** The shape of the tab row. The line type is the base class on its own; the card type adds um-tabs--card. */
  type?: "line" | "card";
  /** Which tab starts open. It is the checked attribute on that radio. */
  selected?: number;
  /** Which tab is open, counted from one. The binding wins over `selected`. */
  modelValue?: number;
  /** Whether the tabs fill the width they are given. It adds um-tabs--stretch. */
  stretch?: boolean;
  /** Where the bar of tabs sits. The bar on top is the base class on its own; the bar under the panel adds um-tabs--bottom. */
  tabPosition?: "top" | "bottom";
}

/** Alert · 警告 — A message that stays in the page and says what the reader has to know: the run failed, the quota is nearly gone, the sync is through. The variant colours the border and the mark, not the text. */
export type AlertVariant = "primary" | "success" | "warning" | "danger" | "info";
export interface AlertProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "alert";
  variant?: AlertVariant;
}

/** Dialog · 对话框 — A panel that asks the reader something, written as a <dialog>. It is shown the way a dialog is shown without JavaScript — open in the markup — and it is closed the way the browser closes one: the close button submits the form around it, and the form's method is dialog. */
export type DialogVariant = "center";
/** Dialog — the sizes it can be rendered at. */
export type DialogSize = "sm" | "md" | "lg";
export interface DialogProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "dialog";
  variant?: DialogVariant;
  size?: DialogSize;
  /** The heading of the panel. */
  title?: string;
  /** Where the title and the actions sit. The start alignment is the base class on its own; the centred one adds um-dialog--center. */
  align?: "start" | "center";
  /** Whether the title and the actions are centred. This is Element Plus's name for the `align` prop's centred value; either one of them centres the panel. */
  center?: boolean;
  /** Whether the panel sits in the middle of the screen rather than in the flow of the page. It adds um-dialog--align-center. */
  alignCenter?: boolean;
  /** Whether the panel takes the whole screen. It adds um-dialog--fullscreen. */
  fullscreen?: boolean;
  /** Whether the panel is opened as the browser's own modal dialog, in the top layer and with the backdrop the browser paints for it. The library paints no mask of its own. */
  modal?: boolean;
  /** Whether the panel is open. The binding wins over the static form, which is the open one. */
  modelValue?: boolean;
  /** Whether the panel carries a close button in its header. */
  showClose?: boolean;
}

/** Drawer · 抽屉 — A panel that slides out from the edge of the page: a side panel with a title, a body and a row of actions. It is held against the edge with fixed positioning, so it stays put while the page moves behind it. */
export type DrawerVariant = "left" | "top" | "bottom" | "inline";
/** Drawer — the sizes it can be rendered at. */
export type DrawerSize = "sm" | "md" | "lg";
export interface DrawerProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "drawer";
  variant?: DrawerVariant;
  size?: DrawerSize;
  /** Which edge the panel slides out from. The right edge is the base class on its own; the other three add um-drawer--left, um-drawer--top or um-drawer--bottom. */
  direction?: "right" | "left" | "top" | "bottom";
  /** Whether the panel is part of the layout instead of floating over it. It adds um-drawer--inline. */
  inline?: boolean;
  /** The heading of the panel. */
  title?: string;
  /** Whether the panel is on the page. A drawer that was not asked for is hidden rather than painted over the page. */
  modelValue?: boolean;
  /** Whether the panel carries a close button in its header. */
  showClose?: boolean;
  /** Whether the panel has a header at all. Without one there is no title and no close button. */
  withHeader?: boolean;
}

/** Loading · 加载中 — A ring that turns while the library waits for something. The ring is two borders with one side left out, and the turn is a keyframe, so it needs neither a timer nor a script. */
export type LoadingVariant = "spinner" | "text" | "overlay";
/** Loading — the sizes it can be rendered at. */
export type LoadingSize = "small" | "medium" | "large";
export interface LoadingProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "loading";
  variant?: LoadingVariant;
  size?: LoadingSize;
  /** The caption beside the ring. It is the message, so it is written as text in the page and not as an attribute. */
  text?: string;
  /** Whether the loading is over. A closed loading is not on the page. */
  closed?: boolean;
  /** Whether the loading covers the whole viewport, whatever shape it is. */
  fullscreen?: boolean;
}

/** Message · 消息 — A short bar that tells the reader what just happened. Element Plus's message is a function that paints the bar and takes it away again; here the bar is a container, and the host decides whether it is on the page. */
export type MessageVariant = "info" | "success" | "warning" | "error";
/** Message — the sizes it can be rendered at. */
export type MessageSize = "sm" | "md" | "lg";
export interface MessageProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "message";
  variant?: MessageVariant;
  size?: MessageSize;
  /** Whether the bar carries a close button. */
  closable?: boolean;
  /** Whether the bar carries a close button. This is Element Plus's name for `closable`; either one of them asks for the button. */
  showClose?: boolean;
  /** Lays the bar on the page rather than over it: the fill behind it and the shadow under it are gone. */
  plain?: boolean;
  /** Says that the bar is one of a group of messages of the same kind. A grouped bar is drawn as a strip of the page, so a stack of them reads as one list. */
  grouping?: boolean;
}

/** Message Box · 消息框 — The narrow, centred box that asks the reader to confirm: a title, a message, and a pair of buttons, with an icon that carries the type. It is written as a <dialog> with a form around it, so the browser's own close is the one that closes it — the buttons are submits inside a form whose method is dialog, and the library installs no listener anywhere. */
export type MessageBoxVariant = "info" | "success" | "warning" | "error";
/** Message Box — the sizes it can be rendered at. */
export type MessageBoxSize = "sm" | "md" | "lg";
export interface MessageBoxProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "message-box";
  variant?: MessageBoxVariant;
  size?: MessageBoxSize;
  /** What the box is asking about. It sets the icon and the accent of the confirm button. */
  type?: "info" | "success" | "warning" | "error";
  /** The heading of the box. */
  title?: string;
  /** The label on the confirm button. */
  confirmText?: string;
  /** The label on the cancel button. */
  cancelText?: string;
  /** Whether the box carries the cross in the corner. */
  showClose?: boolean;
  /** Whether the box carries the cancel button. */
  showCancel?: boolean;
  /** Whether the box carries the cancel button. This is Element Plus's name for `show-cancel`; either one of them asks for the button. */
  showCancelButton?: boolean;
  /** Whether the box carries the confirm button. */
  showConfirmButton?: boolean;
  /** Whether the box asks its question in a field the reader can type in. */
  showInput?: boolean;
  /** What the box is for. An alert asks for one answer, a confirm for two, and a prompt for two and a field to type in. */
  boxType?: "alert" | "confirm" | "prompt";
  /** Whether the title and the message stand in the middle of the box. It adds um-message-box--center. */
  center?: boolean;
  /** Whether the two answers are pills. It adds um-message-box--round-button. */
  roundButton?: boolean;
  /** How big the two answers are. The default size is the base class on its own; the other two add um-message-box--button-sm or um-message-box--button-lg. */
  buttonSize?: "sm" | "md" | "lg";
  /** Whether the box is opened as the browser's own modal dialog, in the top layer and with the backdrop the browser paints for it. The library paints no mask of its own. */
  modal?: boolean;
  /** The type of the answer the box is asking for. The default type is the box's own type; the other five are a fill of their own. */
  confirmButtonType?: "default" | "primary" | "success" | "warning" | "danger" | "info";
  /** The type of the answer that backs out. The default type is the neutral shape, so the eye goes to the answer that is being asked for; the other five are a fill of their own. */
  cancelButtonType?: "default" | "primary" | "success" | "warning" | "danger" | "info";
}

/** Notification · 通知 — A card that reports something the reader did not ask about — a deployment finished, a certificate was renewed. It is wider than a message, and it carries a heading of its own. */
export type NotificationVariant = "info" | "success" | "warning" | "error";
/** Notification — the sizes it can be rendered at. */
export type NotificationSize = "sm" | "md" | "lg";
export interface NotificationProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "notification";
  variant?: NotificationVariant;
  size?: NotificationSize;
  /** The heading of the card. */
  title?: string;
  /** Whether the card carries a close button. */
  closable?: boolean;
  /** Whether the card carries a close button. This is Element Plus's name for `closable`; either one of them asks for the button. */
  showClose?: boolean;
}

/** Popconfirm · 气泡确认 — A bubble that asks before it acts. It hangs off a trigger, and it holds a question and the two real buttons that answer it: confirm and cancel. */
export type PopconfirmVariant = "top" | "left" | "right";
/** Popconfirm — the sizes it can be rendered at. */
export type PopconfirmSize = "sm" | "md" | "lg";
export interface PopconfirmProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "popconfirm";
  variant?: PopconfirmVariant;
  size?: PopconfirmSize;
  /** Where the bubble opens relative to the trigger. The bottom placement is the base class on its own. */
  placement?: "bottom" | "top" | "left" | "right";
  /** The question the bubble asks. */
  title?: string;
  /** The label of the button that goes ahead. */
  confirmText?: string;
  /** The label of the button that backs out. */
  cancelText?: string;
  /** Whether the bubble is switched off. A disabled bubble never opens. It adds um-popconfirm--disabled. */
  disabled?: boolean;
  /** Whether the pointer can enter the bubble. A bubble that cannot be entered lets the pointer through it, so the words in it cannot be selected. It adds um-popconfirm--not-enterable. */
  enterable?: boolean;
  /** Whether the bubble is open. It is the checked attribute on the trigger's own checkbox. */
  visible?: boolean;
  /** Whether the bubble carries the point that says which way it faces. A bubble without one adds um-popconfirm--no-arrow. */
  showArrow?: boolean;
  /** The type of the answer that goes ahead. The default type is the brand colour; the other five are a fill of their own. */
  confirmButtonType?: "default" | "primary" | "success" | "warning" | "danger" | "info";
  /** The type of the answer that backs out. The default type is the neutral shape, so the eye goes to the answer that is being asked for; the other five are a fill of their own. */
  cancelButtonType?: "default" | "primary" | "success" | "warning" | "danger" | "info";
}

/** Popover · 气泡卡片 — A card that floats next to a trigger and holds more than a note: a heading, a body and a row of actions. The trigger is a <summary>, so the card opens and closes with the browser's own disclosure behaviour. */
export type PopoverVariant = "top" | "left" | "right";
/** Popover — the sizes it can be rendered at. */
export type PopoverSize = "small" | "medium" | "large";
export interface PopoverProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "popover";
  variant?: PopoverVariant;
  size?: PopoverSize;
  /** Where the card opens relative to the trigger. The bottom placement is the base class on its own; the other three add um-popover--top, um-popover--left or um-popover--right. */
  placement?: "bottom" | "top" | "left" | "right";
  /** How wide the card is. The measures are in the card's own type, so the card grows with the mood's text instead of holding a fixed pixel width. */
  width?: "small" | "medium" | "large";
  /** The heading of the card. It is a real heading element, not a bold paragraph, so the reader can jump to it. */
  title?: string;
  /** Whether the popover is switched off. A disabled popover never opens. It adds um-popover--disabled. */
  disabled?: boolean;
  /** Whether the pointer can enter the card. A card that cannot be entered lets the pointer through it, so the words in it cannot be selected. It adds um-popover--not-enterable. */
  enterable?: boolean;
  /** Whether the card is open. It is the open attribute on the trigger's own <details>. */
  visible?: boolean;
}

/** Tooltip · 文字提示 — A short note that appears when the reader points at a word or tabs to it. The bubble is drawn by the stylesheet and placed with absolute positioning; the trigger is a real button, so the keyboard opens it as well as the pointer. */
export type TooltipVariant = "top" | "left" | "right";
export interface TooltipProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "tooltip";
  variant?: TooltipVariant;
  /** Where the bubble sits relative to the trigger. The bottom placement is the base class on its own; the other three add um-tooltip--top, um-tooltip--left or um-tooltip--right. */
  placement?: "bottom" | "top" | "left" | "right";
  /** The words in the bubble. It is written as text in the page, and the trigger points at it with aria-describedby so the reader hears it as a description rather than as a stray paragraph. */
  text?: string;
  /** Whether the tooltip is switched off. A disabled tooltip never opens. It adds um-tooltip--disabled. */
  disabled?: boolean;
  /** Whether the pointer can enter the bubble. A bubble that cannot be entered lets the pointer through it, so the words in it cannot be selected. It adds um-tooltip--not-enterable. */
  enterable?: boolean;
  /** Whether the bubble carries the point that says which way it faces. A bubble without one adds um-tooltip--no-arrow. */
  showArrow?: boolean;
  /** Whether the bubble is held open. It adds um-tooltip--visible. */
  visible?: boolean;
}

/** Divider · 分割线 — A rule between two things. It can carry a label in the middle, drop the rules and keep the label, or stand up as a vertical rule. */
export type DividerVariant = "plain" | "vertical";
export interface DividerProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "divider";
  variant?: DividerVariant;
}

/** Watermark · 水印 — A layer of the same word, repeated across a box, to say that what is underneath is a copy. The word is real text in the markup, tiled by the browser rather than baked into a picture. */
export type WatermarkVariant = "diagonal" | "upright";
/** Watermark — the sizes it can be rendered at. */
export type WatermarkSize = "sm" | "md" | "lg";
export interface WatermarkProps {
  /** The component's own id, so a registry can be keyed by it. */
  id: "watermark";
  variant?: WatermarkVariant;
  size?: WatermarkSize;
  /** The word the watermark repeats. */
  text?: string;
  /** How many rows of tiles to write. */
  rows?: number;
  /** How many tiles to write in each row. */
  columns?: number;
}

